import { engineNotice, type SeedAsteroid, type SeedResult } from '@/seed/result'
import type { SeedRule } from '@/seed/rules'

/**
 * FIXTURES: invented data that obeys the `SeedResult` contract, for the gallery only. These are not
 * generated by the engine and match no real seed.
 */

function grid(columns: number, rows: number, palette: string[], salt: number) {
  const cells = new Uint8Array(columns * rows)
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < columns; x++) {
      const edge = x === 0 || y === 0 || x === columns - 1 || y === rows - 1
      const band = Math.floor(((y / rows) * 3 + Math.sin(x / 5 + salt) * 0.4 + 3) % palette.length)
      cells[y * columns + x] = edge ? 255 : Math.abs(band) % palette.length
    }
  }
  return { columns, rows, palette, cells }
}

function asteroid(id: string, isStart: boolean, w: number, h: number, salt: number): SeedAsteroid {
  return {
    id,
    path: `expansion1::worlds/${id}`,
    isStart,
    width: w,
    height: h,
    traits: isStart ? ['traits/GeoActive', 'traits/MetalRich'] : ['expansion1::traits/Volcanoes'],
    geysers: [
      { type: 'hot_steam', x: Math.round(w * 0.3), y: Math.round(h * 0.4) },
      { type: 'OilWell', x: Math.round(w * 0.6), y: Math.round(h * 0.2) },
      { type: 'molten_iron', x: Math.round(w * 0.8), y: Math.round(h * 0.7) },
    ],
    biomes: grid(
      Math.round(w / 4),
      Math.round(h / 4),
      ['Sandstone', 'Jungle', 'Oilfield', 'MagmaCore'],
      salt,
    ),
  }
}

