function result(n: number, score: number, matched: string[], missed: string[]): SeedResult {
  return {
    coordinate: `SNDST-C-${1000 + n}-0-0-0`,
    seed: 1000 + n,
    prefix: 'SNDST-C',
    score,
    maxScore: 7,
    matched,
    missed,
    asteroids: [
      asteroid('SandstoneStart', true, 256, 384, n),
      asteroid('WaterMoonlet', false, 96, 128, n + 1),
      asteroid('RustMoonlet', false, 128, 96, n + 2),
    ],
    engineBuild: 'fixture',
    notice: engineNotice('fixture'),
  }
}

